from torch.utils.cpp_extension import load_inline

# Define the CUDA kernel code with register blocking and warp-level optimization
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Thread block size
#define BLOCK_SIZE 32

// Warp size
#define WARP_SIZE 32

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Block index
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread index
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Each thread computes 4x4 output elements
    const int TILE_SIZE = 4;

    // Register block for output
    float c[TILE_SIZE][TILE_SIZE] = {{0}};

    // Shared memory for tiles of A and B
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    // Starting positions of the tiles
    int aBegin = N * BLOCK_SIZE * by;
    int aEnd = aBegin + N - 1;
    int aStep = BLOCK_SIZE;

    int bBegin = BLOCK_SIZE * bx;
    int bStep = BLOCK_SIZE * N;

    // Loop over tiles
    for (int a = aBegin, b = bBegin; a <= aEnd; a += aStep, b += bStep) {
        // Load tile of A into shared memory (coalesced access)
        if (ty * BLOCK_SIZE + tx < N) {
            As[ty][tx] = A[a + N * ty + tx];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile of B into shared memory (coalesced access)
        if (ty * BLOCK_SIZE + tx < N) {
            Bs[ty][tx] = B[b + N * ty + tx];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        // Synchronize
        __syncthreads();

        // Compute partial dot product for the tile
        #pragma unroll
        for (int k = 0; k < BLOCK_SIZE; k++) {
            // Prefetch values from shared memory
            float a_val = As[ty][k];
            float b_val = Bs[k][tx];

            // Accumulate to registers
            for (int i = 0; i < TILE_SIZE; i++) {
                for (int j = 0; j < TILE_SIZE; j++) {
                    c[i][j] += a_val * b_val;
                }
            }
        }

        // Synchronize before loading next tile
        __syncthreads();
    }

    // Write the computed results to global memory (coalesced access)
    int c_row = by * BLOCK_SIZE + ty;
    int c_col = bx * BLOCK_SIZE + tx;

    for (int i = 0; i < TILE_SIZE; i++) {
        for (int j = 0; j < TILE_SIZE; j++) {
            if ((c_row + i) < N && (c_col + j) < N) {
                C[(c_row + i) * N + (c_col + j)] = c[i][j];
            }
        }
    }
}

